"""Original nutrition and intestinal failure questions."""
from qbank_authoring import question,ref,finalize
IF=ref('ESPEN Chronic Intestinal Failure in Adults: Update 2023','https://academy.espen.org/files/ESPEN-Guidelines/ESPEN_guideline_on_chronic_intestinal_failure_in_adults.pdf')
SBS=ref('AGA Clinical Practice Update: Management of Short Bowel Syndrome','https://gastro.org/clinical-guidance/management-of-short-bowel-syndrome-sbs/')
NICE=ref('NICE CG32: Adult Nutrition Support Recommendations','https://www.nice.org.uk/guidance/cg32/chapter/Recommendations')
GL=ref('GLIM Criteria for Diagnosis of Malnutrition: Consensus Report','https://doi.org/10.1002/jpen.1440')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('What distinguishes intestinal failure from intestinal insufficiency?', 'Gut function is inadequate to maintain health without intravenous supplementation of nutrients and/or water and electrolytes',[
 ('Any history of bowel resection automatically means intestinal failure','Remaining function and the need for IV support determine the distinction.'),('A low albumin alone is sufficient','Albumin is nonspecific and does not define the functional requirement.'),('All chronic diarrhea is intestinal failure regardless of absorption','Many patients maintain nutrition and hydration without IV supplementation.')],
 'Define failure by the support required', '**Intestinal failure is a functional state, not merely a length measurement or diagnosis label.**', ['It can result from short bowel, dysmotility, fistula, obstruction or extensive mucosal disease.','Some patients need IV fluid/electrolytes without full parenteral nutrition.'], '**Assess needs over time rather than assuming permanence.**', ['Rehabilitation and adaptation can reduce support requirements.','Separate acute reversible failure from stable chronic support dependence.'], [['Intestinal insufficiency','Reduced function without IV requirement'],['Intestinal failure','IV supplementation needed'],['Etiology','Several anatomical and functional mechanisms']], [IF])
q('Which situation best represents type III intestinal failure?', 'A metabolically stable patient requiring long-term home parenteral support after intestinal rehabilitation assessment',[
 ('A brief self-limited postoperative ileus','This is typically a short-term acute type I pattern.'),('An unstable complex postoperative patient requiring prolonged inpatient support','This fits the prolonged acute type II framework.'),('Constipation managed with oral laxatives alone','This does not establish intestinal failure.')],
 'The functional classification describes time course and stability', '**Type III denotes chronic intestinal failure in a relatively stable patient.**', ['Type I is acute and usually short-lived.','Type II is prolonged acute failure, often with metabolic instability and complex inpatient needs.'], '**The category helps organize care rather than proving irreversibility.**', ['Some long-term patients can still reduce or stop support after rehabilitation.','Home support needs training, access care and monitoring.'], [['Type I','Acute short-term'],['Type II','Prolonged acute complex/unstable'],['Type III','Chronic relatively stable']], [IF])
q('Under GLIM, what combination is required to diagnose malnutrition after risk screening?', 'At least one phenotypic criterion and at least one etiologic criterion',[
 ('Low albumin as the sole universal criterion','Albumin is influenced by inflammation and is not a stand-alone malnutrition diagnosis.'),('Any one etiologic criterion without a phenotype','The framework requires both domains.'),('A low BMI only, with no etiologic assessment','BMI is one possible phenotypic feature rather than the whole framework.')],
 'Combine evidence of body change with a cause', '**Weight loss, low BMI or reduced muscle mass can supply a phenotypic criterion.**', ['Reduced intake/assimilation or inflammation/disease burden supplies an etiologic criterion.','Screening identifies risk; a diagnostic assessment follows.'], '**Do not miss malnutrition in a person with obesity.**', ['Substantial weight loss and reduced muscle can coexist with a high BMI.','Severity is graded from phenotypic findings within the framework.'], [['Phenotype','Weight, BMI or muscle'],['Etiology','Intake/assimilation or inflammation'],['Diagnosis','At least one from each domain']], [GL])
q('Why is serum albumin an unreliable stand-alone measure of nutritional status in an acutely inflamed patient?', 'Inflammation, redistribution, fluid balance and losses affect albumin independently of nutritional intake',[
 ('Albumin is determined only by protein eaten during the previous meal','Its kinetics and regulation are much more complex.'),('A normal albumin excludes reduced muscle mass','Muscle depletion can occur despite normal albumin.'),('A low value proves that increasing calories alone will correct the underlying illness','The inflammatory or loss process may remain untreated.')],
 'A prognostic laboratory result is not automatically a nutritional diagnosis', '**Albumin can reflect illness burden without quantifying body protein stores.**', ['Use weight trajectory, intake, muscle assessment and disease context.','Consider hepatic synthesis, renal or gut losses and dilution where relevant.'], '**Treat the cause and the nutritional risk in parallel.**', ['Do not withhold nutrition because albumin has not risen.','Do not overfeed in an attempt to normalize a nonspecific marker.'], [['Albumin','Contextual illness/loss marker'],['Muscle and weight trend','Phenotypic nutritional assessment'],['Intake and disease','Etiologic assessment']], [GL,ref('GLIM 5-Year Consensus Update','https://pmc.ncbi.nlm.nih.gov/articles/PMC12053077/')])
q('A severely undernourished patient develops weakness, edema and a marked phosphate fall after carbohydrate-rich feeding begins. What syndrome is most likely?', 'Refeeding syndrome',[
 ('A normal adaptation that never requires monitoring','Electrolyte shifts can produce serious cardiac, neurological and respiratory complications.'),('Isolated iron deficiency as the explanation for the abrupt phosphate fall','Iron deficiency does not explain the characteristic postfeeding metabolic shift.'),('A reason to permanently avoid all nutrition','Nutrition should be adjusted and safely advanced with correction and monitoring, not abandoned.')],
 'A switch from catabolism to insulin-driven anabolism can expose depleted stores', '**Phosphate, potassium and magnesium can shift intracellularly after feeding.**', ['Sodium and water retention and thiamine demand also increase.','A normal baseline electrolyte result does not guarantee adequate total-body stores.'], '**Respond with monitored nutrition adjustment and replacement.**', ['Assess organ effects and the full electrolyte pattern.','Provide thiamine and coordinate an individualized feeding plan.'], [['Trigger','Reintroduction of nutrition after depletion'],['Key laboratory pattern','Falling phosphate, potassium and/or magnesium'],['Management','Controlled feeding, replacement and close monitoring']], [NICE], 'clinical_scenario')
q('According to NICE CG32, what is an appropriate initial maximum energy provision for a high-risk adult refeeding patient who is not in the extreme-risk subgroup?', 'About 10 kcal/kg/day, advanced gradually with close clinical and biochemical monitoring',[
 ('Immediate full calculated calories regardless of depletion','This can precipitate dangerous metabolic shifts in a high-risk patient.'),('No calories for several weeks in every case','Prolonged starvation is not the recommended prevention strategy.'),('A fixed 3,000 kcal/day irrespective of body weight','Risk-based initial provision is not a universal fixed total.')],
 'Name the guideline because refeeding protocols differ', '**NICE uses a cautious start for high-risk patients with gradual escalation over several days.**', ['Extreme cases may require an even lower starting level and cardiac monitoring.','Thiamine, electrolyte supplementation and fluid management are part of the plan.'], '**Do not use the calorie number as the entire protocol.**', ['Monitor phosphate, magnesium, potassium, fluid balance and clinical status.','Adjust to evolving abnormalities and the patient’s severity.'], [['NICE high risk','Initial maximum around 10 kcal/kg/day'],['Extreme risk','May require around 5 kcal/kg/day'],['All at-risk feeding','Vitamins, electrolytes and monitoring']], [NICE])
q('Which vitamin should be provided immediately before and during initial feeding in a patient at substantial refeeding risk?', 'Thiamine',[
 ('Vitamin K alone as the specific carbohydrate-metabolism safeguard','Vitamin K does not replace thiamine in oxidative carbohydrate metabolism.'),('Vitamin D alone as sufficient prevention','It does not prevent thiamine-related neurological or metabolic complications.'),('No vitamin unless the serum thiamine result returns low','Treatment should not wait for a potentially delayed assay in a high-risk setting.')],
 'Carbohydrate use increases a critical cofactor requirement', '**Thiamine deficiency can contribute to neurological injury and impaired oxidative metabolism.**', ['Patients with alcohol-related disease or prolonged poor intake may be particularly depleted.','Use the route and dose appropriate to prevention versus suspected deficiency/Wernicke disease.'], '**Combine vitamin support with the rest of the refeeding plan.**', ['Thiamine does not prevent phosphate or potassium shifts on its own.','Monitor fluids and electrolytes while calories advance.'], [['Thiamine','Carbohydrate-metabolism cofactor'],['Electrolyte replacement','Separate essential intervention'],['Suspected Wernicke disease','Urgent therapeutic regimen']], [NICE])
q('An adult cannot swallow safely but has a functioning accessible gastrointestinal tract. Which nutritional route is generally preferred if oral strategies cannot meet needs?', 'Enteral tube feeding',[
 ('Parenteral nutrition automatically because swallowing is impaired','Swallowing failure does not mean intestinal absorption has failed.'),('IV dextrose alone indefinitely as complete nutrition','Dextrose alone does not provide complete protein, lipid and micronutrient needs.'),('Withholding nutrition until swallowing fully normalizes','This may worsen malnutrition when an effective enteral route is available.')],
 'Choose the route by the functioning part of the system', '**Enteral support uses an accessible gut when oral intake is inadequate or unsafe.**', ['Tube location and duration depend on aspiration risk, anatomy and expected recovery.','Parenteral support is used when oral/enteral intake is unsafe, inadequate or not feasible.'], '**Monitor delivery, not merely the prescription.**', ['Interruptions, intolerance and tube problems can reduce actual intake.','A swallowing rehabilitation plan may permit later oral transition.'], [['Unsafe swallow, usable gut','Enteral support'],['Nonfunctional/inaccessible gut','Parenteral assessment'],['Improving oral capacity','Reassess route']], [NICE], 'clinical_scenario')
q('Which anatomical information is most important when estimating nutritional and fluid consequences after extensive bowel resection?', 'Remaining small-bowel length and segment, ileocecal anatomy and whether the colon is in continuity',[
 ('Only the length removed, regardless of what remains','Residual anatomy is more informative than the resected length alone.'),('Only the serum amylase','This does not characterize absorptive anatomy.'),('Only the patient’s current BMI','Current body size does not define future intestinal capacity.')],
 'The remnant determines the functional opportunity', '**Jejunum, ileum and colon have different absorptive and adaptive contributions.**', ['A colon in continuity can salvage fluid, sodium and energy.','Terminal ileal loss affects B12 and bile acid handling.'], '**Use anatomy to tailor rather than standardize advice.**', ['End-jejunostomy fluid strategies differ from those for a colon-containing remnant.','Support requirements can change during adaptation.'], [['Residual segment','Type of absorptive capacity'],['Colon continuity','Fluid and energy salvage'],['Time after resection','Adaptation potential']], [IF,SBS])
q('A patient with a high-output jejunostomy becomes more dehydrated while drinking large amounts of plain water. What is the best explanation?', 'Low-sodium hypotonic fluid can promote net sodium loss into the jejunal lumen',[
 ('Water always increases net sodium absorption regardless of luminal composition','A leaky jejunal segment can lose sodium when exposed to low-sodium fluids.'),('The stoma proves that no oral solution can ever help','An appropriate glucose-saline solution can improve net absorption.'),('All dehydration must be due to renal salt wasting','The high-output intestinal loss is a major plausible mechanism.')],
 'Fluid composition matters in a short jejunal remnant', '**Large volumes of hypotonic drinks can worsen stomal sodium and water loss.**', ['Use a prescribed high-sodium glucose-saline rehydration strategy.','Some patients still need IV saline despite optimized oral management.'], '**Replace measurable losses and assess renal effects.**', ['Track urine output, weight, renal function and electrolytes.','Avoid telling the patient simply to drink unlimited water.'], [['Plain water in net-secretor jejunostomy','Can worsen sodium depletion'],['Glucose-saline ORS','Promotes absorption'],['Persistent failure','May need IV replacement']], [IF,SBS], 'clinical_scenario')
q('Which drink strategy is generally favored in a sodium-depleted high-output jejunostomy?', 'An appropriate high-sodium oral glucose–saline rehydration solution',[
 ('Unlimited fruit juice as the sole fluid replacement','Hypertonic high-sugar low-sodium drinks can worsen output.'),('Unlimited plain tea and water without electrolyte replacement','Hypotonic low-sodium intake can aggravate depletion.'),('A routine low-sodium sports drink assumed equivalent to specialist ORS','Many sports drinks contain too little sodium for this situation.')],
 'Match replacement to the electrolyte content and absorptive mechanism', '**An appropriate ORS supplies both sodium and glucose in a useful formulation.**', ['The required sodium concentration can be substantially higher than in common sports drinks.','Individual prescriptions depend on output and remaining anatomy.'], '**Review the whole daily balance.**', ['Restricting unsuitable drinks is only safe alongside an adequate replacement plan.','Monitor thirst, urine output and biochemical response.'], [['Specialist glucose–saline ORS','Appropriate replacement approach'],['Low-sodium sugary drink','Poor substitute'],['Daily fluid plan','Needs monitoring and adjustment']], [IF,SBS])
q('Which medication is commonly used before meals to reduce intestinal output in short bowel syndrome?', 'Loperamide',[
 ('Lactulose','This osmotic laxative can increase output.'),('Metoclopramide as the routine transit-slowing drug','Its prokinetic action does not provide the desired slowing mechanism.'),('Oral magnesium salts as the primary antimotility therapy','These can worsen diarrhea and do not provide the intended motility effect.')],
 'Slow transit when rapid passage limits absorption', '**Loperamide can improve contact time and reduce output in selected SBS patients.**', ['Meal-related administration can be useful.','Higher specialist doses require attention to cardiac safety and the full medication context.'], '**Do not treat an unexplained new output rise blindly.**', ['Infection, partial obstruction or another reversible cause may require evaluation.','Antimotility treatment complements fluid and nutritional management.'], [['Loperamide','Transit-slowing strategy'],['New abrupt output increase','Assess cause'],['High-dose use','Specialist safety oversight']], [IF,SBS])
q('Why may a PPI help selected patients with high output early after extensive small-bowel resection?', 'It reduces gastric acid/secretory load reaching the short remnant',[
 ('It regrows a resected terminal ileum','It has no such anatomical effect.'),('It replaces all pancreatic enzymes automatically','Acid suppression and enzyme replacement have different indications.'),('It removes the need to monitor electrolytes','Large fluid and electrolyte losses can persist.')],
 'Reduce a potentially excessive secretory burden', '**Post-resection gastric hypersecretion can add to intestinal fluid losses.**', ['Acid suppression may be useful particularly in a net-secretory high-output state.','The need should be reviewed over time rather than assumed lifelong.'], '**Judge benefit from output and support requirements.**', ['Continue careful hydration and electrolyte replacement.','Consider adverse effects and absorption of other medicines.'], [['Secretory burden','Potential PPI target'],['Response','Output/support requirement'],['Long-term use','Reassess indication']], [IF,SBS])
q('How does a colon in continuity help a patient with short bowel syndrome?', 'It absorbs water and sodium and salvages energy from bacterial fermentation products',[
 ('It completely replaces terminal ileal B12 absorption','The colon does not restore the specialized ileal B12 pathway.'),('It guarantees independence from all IV support','Residual capacity and disease vary.'),('It makes dietary composition irrelevant','Diet can affect fermentation, output and complications.')],
 'The colon adds a salvage compartment', '**Fermentation of unabsorbed carbohydrate produces short-chain fatty acids that can be absorbed.**', ['Fluid and sodium absorption can improve the balance.','A colon-containing remnant has a different nutritional strategy from an end-jejunostomy.'], '**Account for associated risks as well as benefits.**', ['Enteric hyperoxaluria and D-lactic acidosis are relevant in selected anatomy.','Clinical response still determines support needs.'], [['Colon continuity','Fluid and energy salvage'],['No colon','Different fluid strategy'],['Complication risk','Anatomy-specific assessment']], [IF,SBS])
q('Which deficiency requires particular attention after extensive terminal ileal resection?', 'Vitamin B12 deficiency',[
 ('Vitamin C deficiency exclusively because all vitamin C is absorbed only in the ileum','That anatomical premise is incorrect.'),('Iron deficiency solely because the terminal ileum is the main iron uptake site','Iron is mainly absorbed proximally.'),('Complete inability to absorb every amino acid','General amino-acid absorption is not limited to the terminal ileum.')],
 'Specialized absorption creates a predictable vulnerability', '**The terminal ileum absorbs the intrinsic factor–B12 complex.**', ['Body stores can delay clinical manifestation for years.','Bile acid malabsorption and fat-soluble vitamin problems may coexist depending on resection extent.'], '**Monitor and replace rather than waiting for neurological injury.**', ['A normal early post-resection blood count does not exclude future deficiency.','The route of B12 replacement depends on the clinical setting and absorptive capacity.'], [['Terminal ileum','B12 and bile acid uptake'],['Duodenum/proximal bowel','Important iron absorption'],['Long-term follow-up','Deficiency surveillance']], [IF,SBS])
q('A patient with SBS and a colon in continuity develops recurrent calcium oxalate stones. What mechanism is most likely?', 'Fat malabsorption leaves less calcium available to bind oxalate, increasing colonic oxalate absorption',[
 ('The colon completely stops absorbing oxalate after resection','Colonic absorption is central to enteric hyperoxaluria.'),('All dietary calcium should therefore be eliminated','Reducing luminal calcium can increase unbound oxalate and worsen the problem.'),('A high serum calcium is required for enteric hyperoxaluria','The process can occur without hypercalcemia.')],
 'A fat-malabsorption problem can become a renal problem', '**Unabsorbed fatty acids bind calcium and leave more oxalate soluble.**', ['A colon in continuity facilitates the resulting oxalate absorption.','Dehydration further increases stone risk.'], '**Use a targeted dietary and hydration plan.**', ['Oxalate restriction and appropriate calcium with meals may be useful.','Avoid unmonitored blanket calcium or fluid advice in a patient with complex losses.'], [['Fat malabsorption','Calcium binding by fatty acids'],['More soluble oxalate','Greater colonic uptake'],['Prevention','Anatomy-based diet and hydration']], [IF,SBS], 'clinical_scenario')
q('A patient with short bowel and a colon in continuity has episodic ataxia and confusion after carbohydrate-heavy meals. There is metabolic acidosis but routine L-lactate is normal. What diagnosis should be considered?', 'D-lactic acidosis',[
 ('Exclusion of all lactate-related disease because routine lactate is normal','Routine assays generally measure L-lactate, not D-lactate.'),('Insulinoma as the only possible cause regardless of glucose','The carbohydrate-associated acid-base and anatomical pattern suggests another mechanism.'),('A diagnosis requiring a pancreatic mass','This syndrome does not require a pancreatic tumor.')],
 'The assay and the lactate isomer matter', '**Colonic fermentation of poorly absorbed carbohydrate can generate D-lactate in susceptible SBS anatomy.**', ['Neurological episodes and acidosis are characteristic clues.','A specific D-lactate assay may be required.'], '**Treat the episode and reduce the fermentable substrate burden.**', ['Management includes hydration, acid-base support and a specialist dietary plan.','Selected antimicrobial therapy may be used to modify the relevant bacterial overgrowth.'], [['Routine lactate','Usually L-isomer'],['SBS plus colon','Predisposing anatomy'],['Neurological episode after carbohydrate','D-lactate concern']], [IF,SBS], 'clinical_scenario')
q('What is the therapeutic target of teduglutide in selected SBS patients dependent on parenteral support?', 'GLP-2 receptor-mediated enhancement of intestinal absorptive capacity',[
 ('Direct replacement of pancreatic lipase','That is PERT rather than a trophic intestinal hormone strategy.'),('Peripheral mu-opioid receptor blockade','That is a different drug class used for opioid-induced constipation.'),('Eradication of all intestinal bacteria','Teduglutide is not an antimicrobial.')],
 'Intestinal rehabilitation can include a trophic drug', '**Teduglutide is a GLP-2 analogue used in selected patients after optimized conventional care.**', ['The goal can be reduction in parenteral fluid/nutrient requirements.','Not every patient achieves complete independence.'], '**Select and monitor through an experienced intestinal failure program.**', ['Fluid retention, obstruction symptoms and neoplasia-related surveillance require attention.','Adjust parenteral support to measured response rather than stopping it abruptly.'], [['Mechanism','GLP-2 pathway'],['Clinical goal','Reduced parenteral dependence'],['Monitoring','Fluid balance and relevant safety surveillance']], [IF,SBS])
q('A home-PN patient develops fever and rigors shortly after connecting the infusion. What complication requires prompt assessment?', 'Catheter-related bloodstream infection',[
 ('A benign expected effect of every lipid infusion','Temporal association should not be dismissed in a central-line patient.'),('Vitamin B12 deficiency as the sole cause of acute rigors','That does not fit the abrupt febrile infusion-associated syndrome.'),('Normal intestinal adaptation as the explanation','Adaptation does not explain an acute septic presentation.')],
 'A central venous device is a potential bloodstream source', '**Obtain appropriate peripheral and catheter blood cultures and assess for sepsis.**', ['Treat promptly according to severity and local microbiology guidance.','Other infection sources must still be considered.'], '**A salvage decision depends on organism, stability and complications.**', ['Not every line can safely be retained.','Tunnel infection, persistent bacteremia or particular pathogens can favor removal.'], [['Infusion-associated rigors','Line infection concern'],['Cultures','Peripheral and line assessment'],['Line salvage/removal','Organism and severity dependent']], [IF], 'clinical_scenario')
q('Which practice is central to reducing complications during home parenteral nutrition?', 'Structured patient/caregiver training in aseptic catheter care with regular multidisciplinary monitoring',[
 ('Using the catheter for unnecessary manipulations to keep it active','Unnecessary handling increases contamination opportunities.'),('Stopping all laboratory surveillance once the patient is discharged','Stable home care still needs periodic biochemical and clinical assessment.'),('Assuming a single training session eliminates every future problem','Technique review and ongoing support remain important.')],
 'Long-term support is a care system, not just an infusion prescription', '**Aseptic handling reduces catheter infection risk.**', ['Monitor fluid balance, electrolytes, liver tests, micronutrients and nutritional outcomes.','The patient needs a clear pathway for fever, line failure and supply problems.'], '**Reassess whether the prescription still matches actual needs.**', ['Adaptation or disease changes can alter requirements.','Avoid both chronic overfeeding and inadequate replacement.'], [['Training','Aseptic technique and problem recognition'],['Monitoring','Metabolic and nutritional safety'],['Review','Adapt prescription to function']], [IF])
q('Which approach helps reduce intestinal failure-associated liver disease risk during long-term parenteral support?', 'Avoid overfeeding, control sepsis and preserve oral/enteral intake when feasible, with an individualized PN regimen',[
 ('Provide excess glucose indefinitely to normalize albumin','Overfeeding can worsen metabolic and hepatic complications.'),('Treat recurrent line sepsis as unrelated to liver risk','Infection and inflammation can contribute.'),('Stop all enteral intake even when tolerated','Useful enteral stimulation should not be removed without a reason.')],
 'Liver injury in intestinal failure is multifactorial', '**Nutrient load, infection, anatomy and lack of enteral stimulation can all matter.**', ['Adjust energy, lipid strategy and infusion pattern through a specialist team.','Investigate other causes of abnormal liver tests rather than assuming every elevation is PN-related.'], '**Prevent the drivers rather than chasing one laboratory value.**', ['Catheter infection prevention is part of liver protection.','Monitor trends and signs of progressive hepatic disease.'], [['Overfeeding','Modifiable metabolic burden'],['Sepsis','Inflammatory contributor'],['Tolerated enteral intake','Potential protective role']], [IF])
q('What is an appropriate long-term bone-health strategy in chronic intestinal failure?', 'Assess metabolic bone disease risk and monitor bone density and relevant vitamin/mineral status',[
 ('Assume IV nutrition eliminates all osteoporosis risk','Bone disease can still occur through multiple mechanisms.'),('Use serum calcium alone to exclude vitamin D deficiency and low bone mass','Serum calcium can be normal despite substantial bone disease.'),('Avoid all physical activity regardless of fitness','Appropriate activity can support musculoskeletal health.')],
 'A normal serum calcium does not prove normal skeletal health', '**Malabsorption, inflammation, medicines and nutritional imbalance can affect bone.**', ['Vitamin D, calcium, magnesium and other factors require contextual assessment.','Bone density testing and fracture history provide different information from a serum panel.'], '**Treat identified deficits and modifiable risks.**', ['Avoid both inadequate and excessive supplementation.','Use specialist osteoporosis treatment when indicated by the overall fracture-risk assessment.'], [['Biochemistry','Nutrient and metabolic context'],['Bone density','Skeletal measurement'],['Clinical history','Fracture and risk assessment']], [IF])
q('Which situation may justify referral for intestinal transplantation assessment?', 'Life-threatening complications or failure of long-term parenteral support, such as progressive liver disease or major loss of venous access',[
 ('Every stable patient who needs one IV infusion weekly','Stable effective home support does not automatically justify transplant risk.'),('A single mild electrolyte abnormality corrected by prescription adjustment','This alone does not establish support failure.'),('An expectation that transplant has no rejection or infection burden','Transplantation carries substantial immunosuppression and surgical risks.')],
 'Transplant is considered when the balance of long-term support becomes unfavorable', '**Referral is individualized and should occur through an experienced intestinal failure/transplant program.**', ['Progressive hepatic disease, severe recurrent line sepsis and threatened access are important concerns.','A referral assessment does not mean an automatic operation.'], '**Compare realistic alternatives.**', ['Further rehabilitation or support optimization may still help.','Evaluate quality of life, anatomy, comorbidity and transplant risks together.'], [['Stable successful HPN','Continue specialist support'],['Life-threatening HPN complications','Transplant assessment consideration'],['Decision','Individual risk-benefit review']], [IF])
q('After major bowel resection, when should parenteral support be reduced?', 'Gradually, when measured oral/enteral absorption and hydration demonstrate that less IV support is safe',[
 ('Immediately when the patient eats one full meal','Intake does not equal absorption.'),('Only after every laboratory value is above its reference range','That is not a physiological target and can signal overreplacement.'),('Never, because intestinal adaptation cannot occur in adults','Adult adaptation can improve function over time.')],
 'Wean support according to function rather than optimism or habit', '**Weight, urine output, electrolytes, renal function and nutritional status help establish adequacy.**', ['Output and oral intake should be reviewed together.','Dietary rehabilitation and adaptation can change requirements over months to years.'], '**Change one component with a monitoring plan.**', ['Fluid independence and calorie independence may occur at different times.','A rise in creatinine or falling urine output can indicate unsafe reduction.'], [['Eating','Does not prove adequate absorption'],['Measured stable balance','Supports gradual reduction'],['Deterioration after reduction','Reassess and restore needed support']], [IF,SBS])

